{"status":"candidate","chosen_option":"tree_dp_iterative","assumptions":["The input edges form a tree, as specified."],"observations":[{"statement":"The task is to find a minimum-cost vertex cover with exactly k selected vertices, or report IMPOSSIBLE; n≤200 and k≤30.","source_ids":["task"]},{"statement":"The four supplied examples specify outputs 0, 20, IMPOSSIBLE, and 26, respectively.","source_ids":["public1","public2","public3","public4"]}],"artifact":{"code":"import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    costs = data[2:2 + n]
    adj = [[] for _ in range(n)]
    pos = 2 + n
    for _ in range(n - 1):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    inf = 10**30
    dp = [None] * n
    for u in reversed(order):
        # dp[u][selected][count] is the minimum cost for u's subtree.
        states = [[inf] * (k + 1) for _ in range(2)]
        states[0][0] = 0
        if k >= 1:
            states[1][1] = costs[u]

        for v in adj[u]:
            if parent[v] != u:
                continue
            child = dp[v]
            nxt = [[inf] * (k + 1) for _ in range(2)]
            for selected_u in range(2):
                for count_u in range(k + 1):
                    base = states[selected_u][count_u]
                    if base == inf:
                        continue
                    for selected_v in ((0, 1) if selected_u else (1,)):
                        for count_v in range(k - count_u + 1):
                            val = child[selected_v][count_v]
                            if val != inf:
                                total = count_u + count_v
                                cost = base + val
                                if cost < nxt[selected_u][total]:
                                    nxt[selected_u][total] = cost
            states = nxt
        dp[u] = states

    answer = min(dp[0][0][k], dp[0][1][k])
    print(answer if answer != inf else "IMPOSSIBLE")


if __name__ == "__main__":
    main()
